if(!['all',...sectors.map(s=>s[0])].includes(sector))sector='all';const edits=new Map();
const toolNames={lesson:'ChatGPT / Gemini → наставен текст',image:'ChatGPT / Gemini → достапна функција за слики',video:'ChatGPT / Gemini → сценарио → Google Flow',html:'ChatGPT / Gemini → HTML → прелистувач',tts:'ChatGPT / Gemini → чиста нарација → ElevenLabs',quiz:'ChatGPT / Gemini → прашања и клуч'};
