function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function addFilters(id,list,kind){const host=document.getElementById(id);[['all','Сите'],...list].forEach(([value,label])=>{const b=el('button','chip',label);b.type='button';b.dataset.value=value;b.setAttribute('aria-pressed',value==='all');b.onclick=()=>{if(kind==='sector')sector=value;else type=value;render()};host.append(b)})}
addFilters('sectors',sectors,'sector');addFilters('types',types,'type');
function render(){document.querySelectorAll('#sectors button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.value===sector));document.querySelectorAll('#types button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.value===type));const q=document.getElementById('search').value.trim().toLocaleLowerCase('mk');const visible=data.filter(d=>(sector==='all'||d.sector===sector)&&(type==='all'||d.type===type)&&[d.title,d.outcome,d.prompt,toolNames[d.type],sectors.find(s=>s[0]===d.sector)[1]].join(' ').toLocaleLowerCase('mk').includes(q));const host=document.getElementById('cards');host.replaceChildren();document.getElementById('count').textContent=visible.length+' од '+data.length+' промптови';document.getElementById('empty').hidden=visible.length>0;
visible.forEach(d=>{const card=el('article','card');const top=el('div','card-top');top.append(el('span','',sectors.find(s=>s[0]===d.sector)[1]+' / '+types.find(t=>t[0]===d.type)[1]),el('span','number',String(d.id).padStart(2,'0')));card.append(top,el('h2','',d.title),el('p','outcome',d.outcome),el('div','tool',toolNames[d.type]));const label=el('label','prompt-label','Прилагоди го промптот');label.htmlFor='prompt-'+d.id;const area=el('textarea');area.id=label.htmlFor;area.value=edits.get(d.id)??d.prompt;area.oninput=()=>edits.set(d.id,area.value);card.append(label,area);const actions=el('div','actions');const copy=el('button','copy','Копирај промпт');copy.type='button';const reset=el('button','quiet','Врати оригинал');reset.type='button';const status=el('div','status');status.setAttribute('role','status');copy.onclick=async()=>{try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(area.value);else{area.focus();area.select();if(!document.execCommand('copy'))throw Error('copy')}status.textContent='Промптот е копиран.'}catch{area.focus();area.select();status.textContent='Текстот е избран. Копирај со Ctrl+C.'}};reset.onclick=()=>{edits.delete(d.id);area.value=d.prompt;status.textContent='Вратен е оригиналниот промпт.'};actions.append(copy,reset);card.append(actions,status);const detail=el('div','detail');detail.append(el('strong','','Практична задача'),el('p','',d.task),el('strong','','Пред употреба на час'));const ul=el('ul');checks[d.type].forEach(c=>ul.append(el('li','',c)));detail.append(ul);card.append(detail);host.append(card)})}
document.getElementById('search').oninput=render;document.getElementById('clear').onclick=()=>{sector='all';type='all';document.getElementById('search').value='';render()};render();

document.getElementById("download-local").onclick=()=>{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["<!doctype html>\n<html lang=\"mk\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>ВИ работилница · Библиотека на промптови</title>\n<style>\n:root{--paper:#f7f4ec;--ink:#173332;--muted:#50635d;--teal:#066b61;--line:#cdd5ca;--white:#fffef8}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,\"Segoe UI\",sans-serif;font-size:16px;line-height:1.55}button,input,textarea{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}a{color:var(--teal)}header{border-bottom:1px solid var(--line);padding:19px max(24px,calc((100vw - 1240px)/2));display:flex;justify-content:space-between;gap:20px;font-size:13px;letter-spacing:.05em}.brand{font-weight:800}main{max-width:1288px;margin:auto;padding:42px 24px}.hero{display:grid;grid-template-columns:1.55fr 1fr;gap:50px;align-items:center;margin-bottom:34px}.eyebrow{color:var(--teal);font-size:13px;font-weight:750;text-transform:uppercase;letter-spacing:.14em}h1{font-size:clamp(36px,5vw,64px);line-height:1.08;letter-spacing:-.045em;margin:15px 0 22px;max-width:740px}h1 span{color:var(--teal)}.intro{max-width:690px;font-size:18px;color:var(--muted)}.path{padding:24px;border-left:3px solid var(--teal);background:#e7ede2}.path strong{font-size:21px}.path ol{padding-left:23px;margin-bottom:0}.path li{padding:4px 0}.path small{color:var(--muted)}.controls{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:24px 0;display:grid;gap:15px}.search{width:100%;background:var(--white);border:1px solid #859990;padding:14px 16px;border-radius:4px}.filter-row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.filter-label{width:74px;font-size:13px;font-weight:750}.chip{border:1px solid var(--line);background:transparent;border-radius:4px;padding:7px 12px;font-size:14px;color:var(--ink)}.chip[aria-pressed=true]{background:var(--ink);color:white;border-color:var(--ink)}button:hover{border-color:var(--teal)}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #e09935;outline-offset:3px}.results-bar{display:flex;justify-content:space-between;align-items:center;margin:24px 0 18px}.quiet{background:none;color:var(--teal);border:0;text-decoration:underline;font-size:14px;padding:8px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{background:var(--white);border:1px solid var(--line);padding:23px;min-width:0;display:flex;flex-direction:column}.card-top{display:flex;justify-content:space-between;gap:10px;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:var(--teal);font-weight:750}.number{color:var(--muted)}h2{font-size:22px;line-height:1.3;margin:15px 0 10px;letter-spacing:-.025em}.outcome{font-size:14px;color:var(--muted);margin:0 0 15px;min-height:44px}.tool{font-size:12px;font-weight:650;margin-bottom:14px;min-height:37px}label.prompt-label{font-size:12px;font-weight:750;display:block;margin-bottom:6px}textarea{width:100%;resize:vertical;min-height:190px;background:#f4f5ef;border:1px solid var(--line);padding:12px;color:#29443d;font-size:13px;line-height:1.55;border-radius:2px}.actions{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:12px 0}.copy{background:var(--teal);color:white;border:1px solid var(--teal);padding:9px 16px;border-radius:3px;font-size:14px;font-weight:650}.status{font-size:12px;color:var(--teal);min-height:19px}.detail{border-top:1px solid var(--line);padding-top:12px;margin-top:auto;font-size:13px}.detail strong{font-size:12px}.detail p{margin:5px 0 12px}.detail ul{padding-left:18px;margin:6px 0}.empty{padding:60px 20px;border:1px dashed var(--line);text-align:center}.notes{margin-top:45px;border-top:1px solid var(--line);padding:25px 0;display:grid;grid-template-columns:1fr 1fr;gap:35px}.notes h2{font-size:19px}.notes p{font-size:14px;color:var(--muted)}footer{border-top:1px solid var(--line);padding:20px 24px;text-align:center;font-size:12px;color:var(--muted)}[hidden]{display:none!important}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.hero{gap:28px}}@media(max-width:650px){header{padding:16px 20px;flex-direction:column;gap:3px}main{padding:28px 18px}.hero{grid-template-columns:1fr;gap:15px}.grid,.notes{grid-template-columns:1fr}.path{padding:18px}.filter-label{width:100%}.card{padding:20px}.outcome,.tool{min-height:0}.results-bar{font-size:14px}h1{font-size:42px}}@media(prefers-reduced-motion:no-preference){.card{animation:appear .25s ease}@keyframes appear{from{opacity:.5;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}}\n</style></head><body>\n<header><span class=\"brand\">ВИ / НАСТАВНИЧКА РАБОТИЛНИЦА</span><span>13 октомври 2026 · 08:30–16:30</span></header>\n<main><section class=\"hero\"><div><div class=\"eyebrow\">Сите средни училишта</div><h1>Од добра идеја<br>до <span>наставен материјал.</span></h1><p class=\"intro\">48 промптови за твојот предмет. Избери струка, прилагоди го текстот и создај материјал што учениците ќе го истражуваат.</p><p><strong>ChatGPT · Gemini · Google Flow · ElevenLabs</strong></p></div><aside class=\"path\"><strong>Една тема. Пет чекори.</strong><ol><li>Промпт и наставна цел</li><li>Слика со јасна порака</li><li>Сценарио или HTML-анимација</li><li>Текст и звучна нарација</li><li>Прашања за учениците</li></ol><p><small>Почни со проверен наставен извор. Провери го секој резултат пред употреба.</small></p></aside></section>\n<section class=\"controls\" aria-label=\"Пребарување и филтри\"><label for=\"search\" class=\"eyebrow\">Пронајди промпт</label><input class=\"search\" id=\"search\" type=\"search\" placeholder=\"Пребарај: кожа, клиент, струја, дифузија…\"><div class=\"filter-row\" id=\"sectors\"><span class=\"filter-label\">Образовна област</span></div><div class=\"filter-row\" id=\"types\"><span class=\"filter-label\">Формат</span></div></section>\n<p style=\"font-size:13px;color:var(--muted);margin:18px 0 0\">Измените остануваат додека страницата е отворена. Со освежување се губат — копирај го прилагодениот промпт во документ за да го зачуваш.</p><div class=\"results-bar\"><strong id=\"count\" aria-live=\"polite\"></strong><button class=\"quiet\" id=\"clear\">Исчисти ги филтрите</button></div><section id=\"cards\" class=\"grid\" aria-label=\"Библиотека на промптови\"></section><div id=\"empty\" class=\"empty\" hidden><h2>Нема промптови за овој избор.</h2><p>Пробај друг збор или исчисти ги филтрите.</p></div>\n<section class=\"notes\"><div><h2>Како да ги користиш алатките</h2><p>Во ChatGPT или Gemini подготви текст, сценарио, прашања или код. За слика користи достапна функција за создавање слики. Во <a href=\"https://flow.google.com/\" target=\"_blank\" rel=\"noopener\">Google Flow</a> пробај кратки визуелни сцени; додади проверени ознаки во подоцнежна обработка. Во <a href=\"https://elevenlabs.io/text-to-speech\" target=\"_blank\" rel=\"noopener\">ElevenLabs</a> залепи само нарација, без инструкциите за нејзино пишување. Достапноста, ограничувањата и изговорот зависат од алатката и сметката.</p></div><div><h2>Инспирација и проверка</h2><p>Самостојно адаптирана библиотека, инспирирана од моделот на пребарливи промптови на <a href=\"https://igorbogdanoski.github.io/prompts.chat/\" target=\"_blank\" rel=\"noopener\">prompts.chat</a> и идејата за анимации со код од <a href=\"https://github.com/yihui-dev/awesome-opus5-5-videos\" target=\"_blank\" rel=\"noopener\">awesome-opus5-5-videos</a>. Промптовите се оригинално составени за средно стручно, општообразовно и гимназиско образование; видеата од репото не се прегледани. Ова се почетни инструкции, а не научно валидирани материјали. Медицинските и хемиските теми се концептуални; користи измислени случаи.</p></div></section></main><footer>Избери → прилагоди → создај → провери → употреби на час · Страницата работи локално; ВИ-алатките бараат интернет.</footer>\n<script>\nconst sectors=[['medical','Медицинска'],['services','Лични услуги'],['technical','Техничка'],['chemistry','Хемиска'],['general','Општообразовни'],['gym','Гимназии']];\nconst types=[['lesson','Текст / час'],['image','Слика'],['video','Видео'],['html','Анимација'],['tts','Нарација'],['quiz','Квиз']];\nconst common='\\n\\nОдделение: [внеси]\\nИсход од учење: [внеси]\\nОдобрен наставен извор: [залепи релевантен текст и наведи извор]\\nКористи го изворот за стручните факти. Ако недостига податок, означи „Потребна проверка од наставник“. Пиши на македонски јазик, со соодветна сложеност за одделението. Разграничи факт, поедноставување и измислен пример.';\nconst data=[\n['medical','lesson','Разговор со пациент','Учениците препознаваат јасна и почитувачка комуникација.','Напиши сценарио за 20-минутна лекција за комуникација со пациент. Користи целосно измислен разговор со шест реплики за прием и објаснување на општа информација. Додај споредба на две формулации, улоги за работа во пар и прашање за рефлексија. Не давај дијагнози, третман или персонализирани клинички совети. Не користи вистински лични податоци.','Во парови подобрете една нејасна реплика.'],\n['medical','image','Кожата, слој по слој','Учениците ги поврзуваат слоевите со нивните основни функции.','Создај чиста шематска образовна илустрација на пресек на кожата според приложениот извор. Прикажи ги епидермисот, дермисот и поткожното ткиво само ако изворот ги содржи. Користи различни бои и остави празни места за ознаките што наставникот ќе ги внесе по проверка. Не прикажувај болести или третмани. Наведи предложени ознаки во одделен текст и означи дека пресекот е поедноставен.','Додајте три проверени ознаки и легенда.'],\n['medical','video','Патот на крвта','Учениците го следат редоследот на движење во шематски модел.','Подготви сценарио за 30-секундно концептуално видео за движење на крвта низ срцето според изворот. Во табела со пет сцени наведи траење, камера, приказ, насока на стрелките и нарација. Користи ист стил низ сите сцени. Не прикажувај болести или интервенции. По табелата дај кратки инструкции за Google Flow за секоја сцена без вграден текст; ознаките се додаваат од наставникот по проверка. Означи ограничувања на моделот.','Проверете ги насоките на стрелките пред создавање видео.'],\n['medical','html','Срце: следен чекор','Учениците го објаснуваат редоследот со паузирање на моделот.','Создај една самостојна HTML-датотека за шематски пат на крвта низ срцето според изворот. Вклучи копчиња Почни, Пауза, Следен чекор и Почни одново, големи проверливи ознаки и легенда. Секоја фаза нека се активира и со тастатура. Не користи надворешни библиотеки. Не претставувај бои како реалната боја на крвта. Додај текст за поедноставувањата и едно прашање за предвидување.','Паузирајте ја анимацијата и објаснете го следниот чекор.'],\n['medical','tts','Нарација за кожата','Учениците ја поврзуваат слушнатата нарација со пресекот.','Подготви нарација од 90–120 зборови за основните слоеви на кожата според изворот. Користи кратки реченици и мирно темпо. Испорачај два одделни дела: 1. НАРАЦИЈА, само текст за читање без сценски упатства; 2. ПРОВЕРКА, стручни термини чиј изговор треба да се слушне и провери. Не додавај здравствени совети. Текстот од првиот дел ќе се залепи во ElevenLabs; не тврди дека изговорот е гарантиран.','Слушнете го звукот и проверете два стручни термини.'],\n['medical','quiz','Анатомски поими','Учениците разликуваат структура, функција и просторен однос.','Создај шест прашања за основните анатомски поими од изворот: две со избор, две за поврзување и две со краток одговор. За секое дај точен одговор, кратко образложение и конкретен дел од изворот. Избегнувај двосмислени опции и клинички одлуки. Направи верзија за ученици и одделен клуч за наставникот.','Заменете едно прашање што проверува само меморирање.'],\n['services','lesson','Консултација со клиент','Учениците поставуваат јасни прашања и потврдуваат очекувања.','Создај 20-минутна активност за разговор со клиент пред услуга. Користи измислен клиент што сака промена на стил. Додај пет отворени прашања, пример за потврдување на договореното и две улоги за игра. Не претпоставувај медицински состојби и не предлагај дијагностика или третман. Користи професионален и почитувачки јазик.','Одиграјте двоминутна консултација во парови.'],\n['services','image','Три варијанти на фризура','Учениците ги споредуваат формата, должината и пропорциите.','Создај три јасно различни концептуални скици за фризура на истиот измислен возрасен модел, во ист агол и осветлување. Разликите нека бидат во должина, волумен и силуета, според изворот. Користи неутрална позадина и без текст во сликата. Додај одделен опис на разликите и прашање за споредба. Не ветувај идентичен реален резултат.','Опишете ги разликите без вредносни судови за изгледот.'],\n['services','video','Разговор во три сцени','Учениците ја препознаваат структурата на консултацијата.','Подготви сценарио за три кратки сцени: поздрав, разјаснување на желбите и потврда на договорот. Користи измислени возрасни ликови во професионален простор. За секоја сцена дај визуелна инструкција за Google Flow, траење и одделен дијалог. Задржи ист опис на ликовите, облеката и просторот. Не барај читлив текст во видеото; титловите ќе се додадат и проверат подоцна.','Проверете дали последната сцена ги потврдува очекувањата.'],\n['services','html','Организирај го просторот','Учениците го образложуваат распоредот на работното место.','Создај една самостојна HTML-активност за распоред на работно место за лични услуги. Вклучи шест предмети и три зони според приложениот одобрен материјал. Изборот на предмет и зона нека биде со копчиња, без задолжително влечење. Додај повратна информација заснована на изворот, ресетирање и кратко образложение. Ако изворот не дефинира зона, побарај дополнување. Не претставувај активноста како сертификација за безбедност.','Образложете една одлука за распоред.'],\n['services','tts','Добредојде во салонот','Учениците слушаат пример за јасен професионален говор.','Напиши нарација од 90–120 зборови за добредојде и објаснување на текот на консултацијата со измислен клиент. Испорачај НАРАЦИЈА како чист текст за ElevenLabs и одделен дел ПРОВЕРКА со зборови за проверка на изговор и тон. Избегнувај маркетиншки ветувања и медицински тврдења. Нарацијата нека биде топла, јасна и професионална.','Снимката споредете ја со ваш сопствен прочитан пример.'],\n['services','quiz','Професионален избор','Учениците ја образложуваат соодветната комуникација.','Напиши шест кратки измислени сценарија за комуникација со клиент и организација на работно место според изворот. За секое понуди три реакции, една најсоодветна и образложение. Не поставувај прашања за дијагноза или третман. Дај одделна ученичка верзија и клуч. Ако повеќе реакции се оправдани, преработи го сценариото за да има јасни критериуми.','Дискутирајте зошто една реакција е посоодветна.'],\n['technical','lesson','Омов закон во контекст','Учениците ги поврзуваат напонот, струјата и отпорот.','Подготви 25-минутна лекција за Омов закон според изворот. Вклучи ознаки, единици, еден целосно решен пример и две задачи со одговори. Објасни за кои услови важи моделот. Додај прашање за предвидување пред пресметката. Користи само идеализирано коло; не давај упатства за работа со мрежен напон или практично поврзување.','Пред пресметката предвидете што ќе се случи со струјата.'],\n['technical','image','Јасна шема на коло','Учениците ги читаат симболите и ознаките.','Подготви образовна шема на едноставно идеализирано коло со извор и еден отпорник според изворот. Користи јасни стандардни симболи, без декоративни елементи. Ако алатката за слика не ги прикажува точно, предложи векторска шема или код. Додај одделна листа на ознаки U, I, R и нивните единици за наставникот да ги внесе по проверка. Не давај практични електрични упатства.','Проверете го секој симбол со наставниот извор.'],\n['technical','video','Два запченика','Учениците ја предвидуваат насоката на вртење.','Создај сценарио за 20-секундно концептуално видео на два меѓусебно зафатени запченика, според изворот. Прикажи фронтална камера, означена точка на секој запченик и спротивни насоки кога моделот го бара тоа. Дај три сцени и посебни визуелни инструкции за Google Flow. Избегнувај тврдења за точна геометрија од генерираното видео; наведи што наставникот треба да провери. Додај пауза за предвидување.','Проверете дали прикажаното движење е механички доследно.'],\n['technical','html','Промени U и R','Учениците ја испитуваат врската I = U / R.','Создај една offline HTML-датотека за идеализиран Омов закон. Вклучи лизгачи за U од 1 до 12 V и R од 1 до 100 Ω, видливи единици и пресметка I = U / R. Прикажи ја вредноста и едноставен график со јасни оски. Додај ресетирање, пристапни текстуални полиња и прашање за предвидување. Наведи дека е идеализиран модел, без упатства за реално поврзување.','Удвојте го отпорот и објаснете ја промената.'],\n['technical','tts','Објасни Омов закон','Учениците слушаат формула објаснета со зборови и единици.','Подготви нарација од 90–120 зборови за Омов закон според изворот. Формулата прочитај ја со зборови и објасни ги единиците. Дај еден едноставен проверлив бројчен пример. Испорачај чиста НАРАЦИЈА за ElevenLabs, а во одделен дел ПРОВЕРКА наведи ги броевите, единиците и изговорот на термини. Не вметнувај сценски инструкции во нарацијата.','Проверете ја пресметката и изговорот на единиците.'],\n['technical','quiz','Предвиди, па пресметај','Учениците прават предвидување и го поткрепуваат со пресметка.','Создај шест задачи за идеализиран Омов закон според изворот: две за единици, две за предвидување и две бројчени задачи. Одговорите нека вклучуваат формула, замена, единица и објаснување. Користи позитивни ненулти отпори и едноставни бројки. Дај ученичка верзија и одделен клуч. Не додавај практични упатства за електрична инсталација.','Решете една задача на два начина: со зборови и со формула.'],\n['chemistry','lesson','Честички и состојби','Учениците го поврзуваат моделот на честички со агрегатната состојба.','Подготви 25-минутна концептуална лекција за цврста, течна и гасовита состојба според изворот. Спореди распоред, движење и меѓусебно растојание на честичките. Додај активност со цртежи, една честа заблуда и прашање за објаснување. Не сугерирај дека честичките се зголемуваат при загревање. Не давај лабораториски процедури.','Нацртајте три модели и наведете едно ограничување.'],\n['chemistry','image','Три модели на честички','Учениците споредуваат распоред и движење.','Создај образовна илустрација со три еднакви панели за цврста, течна и гасовита состојба според изворот. Користи честички со иста големина, доследна боја и јасен распоред. Стрелките за движење нека бидат објаснети во одделна легенда. Без вграден текст; ознаките ќе ги додаде наставникот. Наведи дека моделот е шематски и не е во реален размер.','Проверете дали честичките имаат иста големина во сите панели.'],\n['chemistry','video','Дифузија во модел','Учениците го објаснуваат ширењето со движење на честички.','Подготви сценарио за 25-секундно концептуално видео за дифузија во затворен шематски простор според изворот. Покажи две бои на честички, почетна нерамномерна распределба и постепено мешање со случајно движење. Задржи ист број и големина на честички. Дај четири сцени со траење и инструкции за Google Flow, одделно од нарацијата. Не додавај експериментални постапки. Наведи дека генерираниот приказ треба да се провери.','Објаснете зошто движењето не завршува по мешањето.'],\n['chemistry','html','Дифузија: набљудувај','Учениците споредуваат почетна и подоцнежна распределба.','Создај една самостојна HTML-симулација за концептуална дифузија. Прикажи 40 честички во правоаголник, половина од секоја боја, со случајно движење и одбивање од ѕидовите. Додај Почни, Пауза и Ресетирај, како и текстуален опис за пристапност. Зачувај ги бројот и големината на честичките. Наведи дека е илустративен модел без реални временски и просторни размери, а не физички валидирана симулација.','Споредете ја распределбата во два моменти.'],\n['chemistry','tts','Слушни ја промената','Учениците ја објаснуваат промената на состојба со моделот.','Напиши нарација од 90–120 зборови за промена на агрегатна состојба според изворот. Разграничи движење и распоред на честичките од нивната големина. Користи еден концептуален пример без лабораториски инструкции. Испорачај чиста НАРАЦИЈА за ElevenLabs и одделен дел ПРОВЕРКА со поими и места каде треба да се провери изговорот. Не додавај музички или сценски упатства во нарацијата.','Слушнете и проверете дали моделот е точно објаснет.'],\n['chemistry','quiz','Откриј ја заблудата','Учениците ги коригираат погрешните објаснувања.','Создај шест концептуални прашања за агрегатни состојби и дифузија според изворот. Вклучи две заблуди што ученикот треба да ги коригира, две споредби и две прашања за предвидување. За секое дај одговор, образложение и упатување кон доставениот текст. Без лабораториски процедури или опасни супстанции. Испорачај ученичка верзија и одделен клуч.','Преработете една неточна реченица во точно објаснување.'],\n['technical','image','Контактор — конструктивен приказ','Учениците идентификуваат делови и функции.','Користи фотографија и datasheet на контактор за концептуален пресечен приказ. Означи го куќиштето, намотката и главните контакти само ако се потврдени. Подготви одделни ознаки за наставникот. Не измислувај пинови или измерени параметри.','Проверете две ознаки со документот.'],\n['technical','lesson','Омов закон — два предизвика','Учениците ги поврзуваат U, I и R.','Подготви 45-минутна активност за Омов закон со два решени нисконапонски идеализирани примера, четири самостојни задачи, единици и клуч. Побарај точна наставна цел. Без опасни лабораториски постапки.','Одредете дали единиците се согласни.'],\n['technical','html','PLC-секвенца во симулатор','Учениците следат состојби и премини.','Создај самостоен HTML-симулатор за транспортна лента со четири означени состојби. Нека има Почни, Пауза, Чекор и Ресет, копчиња достапни со тастатура и објаснување. Нема реално управување со опрема или безбедносни системи.','Провери дали ресетот ја враќа почетната состојба.'],\n['technical','video','Магнетно поле на соленоид','Учениците ја објаснуваат причинската врска меѓу струја и поле.','Подготви 30-секундно сценарио во пет кадри за концептуално магнетно поле на соленоид. Прикажи насока на струја и поле според избран конзистентен модел, со одделна нарација и наставничка листа за проверка. Не прикажувај измерени вредности.','Проверете го правилото на десната рака.'],\n['technical','quiz','PCB: препознај шест компоненти','Учениците разликуваат вид и функција на компонента.','Според приложена фотографија на PCB, подготви визуелен квиз со шест проверливи компоненти, нумерирани ознаки и одделен наставнички клуч. Ако компонентата не може да се идентификува, не ја вклучувај.','Пронајдете една причина зошто не е јасна идентификацијата.'],\n['technical','tts','Кратка нарација за трансформатор','Учениците слушаат научно точни електротехнички поими.','Подготви 100–120 зборови на стандарден македонски за основен принцип на трансформатор, врз основа на проверен извор. Одделно испорачај само нарација за ElevenLabs и термини за слушна проверка. Не тврди дека DC создава непрекината трансформаторска индукција во стационарна состојба.','Провери изговор на примарна и секундарна намотка.'],\n['technical','image','Термографија без лажно мерење','Учениците разликуваат симулација од мерење.','Создај термографски концептуален приказ врз фотографија од електрична табла, со натпис СИМУЛАЦИЈА, без конкретни температури и без тврдење за дефекти. Користи го за разговор за ограничувањата на мерењето.','Објаснете зошто боите не се измерена температура.'],\n['technical','lesson','Безбедна анализа на неисправност','Учениците аргументираат безбедни дијагностички чекори.','Подготви измислен случај на електромотор што не стартува, со симулирани диагностички податоци, дрво на хипотези, рубрика и правила за работа без физички интервенции. Не нуди инструкции за работа под напон.','Разликувај хипотези од потврдени податоци.'],\n['general','lesson','Математика — пресек на функции','Учениците го проверуваат графикот со пресметка.','Создај час за y=2x+1 и y=-x+4, со аналитички точен пресек (1,3), графички приказ и четири прашања. Означи ги координатните оски правилно и додај клуч со постапка.','Проверете дали (1,3) лежи на двете прави.'],\n['general','image','Физика — график на брзина','Учениците поврзуваат график и растојание.','Создај читлив график v(t)=4 m/s за 0≤t≤5 s, со точни оски и единици. Нека наставничкото објаснување ја поврзе површината под графикот со патека 20 m. Без други непроверени податоци.','Пресметајте ја патеката независно.'],\n['general','video','Историски извор во пет сцени','Учениците разликуваат доказ од толкување.','Побарај проверен краток историски извор. Направи сценарио за пет кадри со прашања кој, кога, зошто и колку е веродостоен. Не генерирај вистински историски цитати и датуми што не се доставени.','Одделете еден факт од интерпретација.'],\n['general','quiz','Англиски B1 — дијалог','Учениците водат функционален разговор.','Направи шест прашања за измислен B1-разговор на англиски во музеј на технологија, со речник, точни одговори и кратка активност во парови. B1 е пример, не претпоставка за официјална програма.','Испробајте ги улогите во парови.'],\n['general','html','Географија — климадијаграм','Учениците читаат температурни и врнежни податоци.','Создај една HTML-датотека што визуелизира месечни температури и врнежи внесени од наставникот. Не измислувај податоци. Додај соодветни единици, текстуална табела и три прашања. Без надворешни библиотеки.','Провери ги оските и единиците.'],\n['general','tts','Македонски јазик — аргументирање','Учениците слушаат структура на аргумент.','Напиши оригинален краток текст за улогата на технологијата во учењето со јасно тврдење, доказ и образложение. Дај чиста нарација од 100 зборови и одделни прашања за слушање. Без измислени извори.','Најдете го тврдењето и неговата поткрепа.'],\n['general','image','Биологија — поедноставена клетка','Учениците разликуваат основни клеточни структури.','Создај образовна шема за еукариотска клетка според доставениот учебнички извадок. Означи ги само спомнатите структури, со одделен клуч. Избегнувај мешање на растителни и животински специфични структури.','Проверете кои структури се присутни.'],\n['general','quiz','Граѓанско — медиумска писменост','Учениците оценуваат веродостојност на тврдење.','Создај пет измислени медиумски пораки со прашања за извор, автор, датум и доказ. Додај разјаснување и клуч со критериуми без партиска или политичка агитација.','Дискутирајте проверливост на едно тврдење.'],\n['gym','lesson','Извод на функција и допирница','Учениците ја поврзуваат аналитиката со график.','Подготви час за f(x)=x² и допирница во x=1. Аналитички потврди f(1)=1, f’(1)=2 и y=2x−1, со илустрација, вежби и клуч. Не користи декоративно неточни графици.','Проверете допир во точката (1,1).'],\n['gym','image','Електромагнетна индукција','Учениците следат промена на магнетен флукс.','Користи проверен извор за да создадеш концептуална шема за намотка и променлив магнетен флукс со насоки на индуцирана ЕМС. Ако знаците не се зададени, прво дефинирај конвенција.','Проверете ја насоката според Лензовото правило.'],\n['gym','video','Литература — споредување мотиви','Учениците анализираат текст преку визуелни докази.','Побарај два кратки проверени книжевни извадоци. Направи storyboard од четири сцени што прикажува мотив, перспектива и атмосфера без измислување цитати или детали надвор од текстот.','За секоја сцена наведете текстуален доказ.'],\n['gym','html','Информатика — алгоритми','Учениците споредуваат линеарно и бинарно пребарување.','Направи интерактивна HTML-демонстрација на линеарно и бинарно пребарување по иста сортирана листа. Додај Следен чекор, Ресет и бројач на споредби. Објасни дека бинарното пребарување бара сортирана низа.','Проверете ја сортираноста и бројот на чекори.'],\n['gym','tts','Филозофија — аргумент и контрааргумент','Учениците препознаваат претпоставка и доказ.','Подготви две кратки спротивставени позиции за човековата автономија во дигиталното општество со јасни претпоставки и прашања, без наметнување заклучок. Оддели чиста аудио нарација од методичките инструкции.','Идентификувајте ги претпоставките.'],\n['gym','quiz','Хемија — периодични трендови','Учениците објаснуваат трендови во периодниот систем.','Создај шест прашања за атомски радиус и електронегативност, со точни одговори и објаснувања од проверен извор. Означи кога поедноставениот тренд има исклучоци. Без опасни лабораториски постапки.','Проверете по едно образложение од извор.'],\n['gym','image','Биологија — негативна повратна врска','Учениците го разликуваат стимулот и одговорот.','Создај шематски дијаграм за хомеостатска негативна повратна врска на температура, со рецептор, центар на обработка и ефектор според учебник. Не давај медицински совети или индивидуални дијагнози.','Означете која врска е негативна.'],\n['gym','lesson','STEAM — енергија и податоци','Учениците интегрираат физика, математика и информатика.','Подготви 45-минутна активност за симулирани податоци од електрична потрошувачка со табела, точен график, пресметка на енергија и едноставен рубрикатор. Не барај работа со мрежен напон.','Проверете ги единиците и методологијата.']\n].map((r,i)=>({id:i+1,sector:r[0],type:r[1],title:r[2],outcome:r[3],prompt:r[4]+common,task:r[5]}));\nlet sector='all',type='all';const edits=new Map();\nconst toolNames={lesson:'ChatGPT / Gemini → наставен текст',image:'ChatGPT / Gemini → достапна функција за слики',video:'ChatGPT / Gemini → сценарио → Google Flow',html:'ChatGPT / Gemini → HTML → прелистувач',tts:'ChatGPT / Gemini → чиста нарација → ElevenLabs',quiz:'ChatGPT / Gemini → прашања и клуч'};\nconst checks={lesson:['Фактите се поткрепени со изворот.','Активноста го проверува избраниот исход.'],image:['Формите, симболите и ознаките се проверени.','Поедноставувањата се јасно наведени.'],video:['Секоја сцена е стручно и визуелно проверена.','Нарацијата и приказот се усогласени.'],html:['Копчињата и ресетирањето работат.','Моделот, единиците и ограничувањата се проверени.'],tts:['Во ElevenLabs е внесена само нарацијата.','Изговорот и стручната точност се проверени со слушање.'],quiz:['Одговорите се проверени со изворот.','Прашањата се јасни и соодветни за одделението.']};\nfunction el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}\nfunction addFilters(id,list,kind){const host=document.getElementById(id);[['all','Сите'],...list].forEach(([value,label])=>{const b=el('button','chip',label);b.type='button';b.dataset.value=value;b.setAttribute('aria-pressed',value==='all');b.onclick=()=>{if(kind==='sector')sector=value;else type=value;render()};host.append(b)})}\naddFilters('sectors',sectors,'sector');addFilters('types',types,'type');\nfunction render(){document.querySelectorAll('#sectors button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.value===sector));document.querySelectorAll('#types button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.value===type));const q=document.getElementById('search').value.trim().toLocaleLowerCase('mk');const visible=data.filter(d=>(sector==='all'||d.sector===sector)&&(type==='all'||d.type===type)&&[d.title,d.outcome,d.prompt,toolNames[d.type],sectors.find(s=>s[0]===d.sector)[1]].join(' ').toLocaleLowerCase('mk').includes(q));const host=document.getElementById('cards');host.replaceChildren();document.getElementById('count').textContent=visible.length+' од 48 промптови';document.getElementById('empty').hidden=visible.length>0;\nvisible.forEach(d=>{const card=el('article','card');const top=el('div','card-top');top.append(el('span','',sectors.find(s=>s[0]===d.sector)[1]+' / '+types.find(t=>t[0]===d.type)[1]),el('span','number',String(d.id).padStart(2,'0')));card.append(top,el('h2','',d.title),el('p','outcome',d.outcome),el('div','tool',toolNames[d.type]));const label=el('label','prompt-label','Прилагоди го промптот');label.htmlFor='prompt-'+d.id;const area=el('textarea');area.id=label.htmlFor;area.value=edits.get(d.id)??d.prompt;area.oninput=()=>edits.set(d.id,area.value);card.append(label,area);const actions=el('div','actions');const copy=el('button','copy','Копирај промпт');copy.type='button';const reset=el('button','quiet','Врати оригинал');reset.type='button';const status=el('div','status');status.setAttribute('role','status');copy.onclick=async()=>{try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(area.value);else{area.focus();area.select();if(!document.execCommand('copy'))throw Error('copy')}status.textContent='Промптот е копиран.'}catch{area.focus();area.select();status.textContent='Текстот е избран. Копирај со Ctrl+C.'}};reset.onclick=()=>{edits.delete(d.id);area.value=d.prompt;status.textContent='Вратен е оригиналниот промпт.'};actions.append(copy,reset);card.append(actions,status);const detail=el('div','detail');detail.append(el('strong','','Практична задача'),el('p','',d.task),el('strong','','Пред употреба на час'));const ul=el('ul');checks[d.type].forEach(c=>ul.append(el('li','',c)));detail.append(ul);card.append(detail);host.append(card)})}\ndocument.getElementById('search').oninput=render;document.getElementById('clear').onclick=()=>{sector='all';type='all';document.getElementById('search').value='';render()};render();\n</script></body></html>\n\r\n"],{type:"text/html;charset=utf-8"}));a.download="vi-obuka-nastavnici.html";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
// Link the standalone visual prompt library without changing the existing 24 prompts.
(function(){const main=document.querySelector("main");if(!main)return;const p=document.createElement("p");p.style.cssText="margin:0 0 18px;padding:14px 18px;background:#e3f2fa;border-left:4px solid #0756b4";const a=document.createElement("a");a.href="../visual-lab/";a.textContent="AI Visual Lab → 50 визуелни команди за техничка настава";a.style.fontWeight="800";p.append(a);main.insertBefore(p,main.firstChild);})();
